using MeterForge.Kata;

// Ported from tests/MeterForge.Domain.Tests/Pricing/PriceVersionTests.cs, plus the edges of a one-day version.
public sealed class PriceSelectionTests
{
    private static readonly Guid ProductId = Guid.NewGuid();

    private static PriceVersion Version(decimal amount, DateOnly from, DateOnly? to) =>
        new(Guid.NewGuid(), ProductId, new Money(amount, "USD"), from, to);

    [Fact(DisplayName = "on the changeover date only the NEW price applies (half-open [from, to), docs/sprints/sprint-03.md:3)")]
    public void Select_AdjacentBoundary_ChoosesNewVersionOnly()
    {
        var boundary = new DateOnly(2026, 7, 1);
        var oldPrice = Version(10m, new DateOnly(2026, 1, 1), boundary);
        var newPrice = Version(12m, boundary, null);

        var selected = PriceSelector.Select([oldPrice, newPrice], ProductId, boundary);

        Assert.Equal(newPrice.Id, selected.Id);
    }

    [Fact(DisplayName = "the day before the changeover still bills the old price")]
    public void Select_DayBeforeBoundary_ChoosesOldVersion()
    {
        var boundary = new DateOnly(2026, 7, 1);
        var oldPrice = Version(10m, new DateOnly(2026, 1, 1), boundary);
        var newPrice = Version(12m, boundary, null);

        Assert.Equal(oldPrice.Id, PriceSelector.Select([oldPrice, newPrice], ProductId, boundary.AddDays(-1)).Id);
    }

    [Fact(DisplayName = "a one-day version [d, d+1) applies on d and NOT on d+1")]
    public void OneDayVersion_DoesNotApplyOnItsEndDate()
    {
        var day = new DateOnly(2026, 3, 14);
        var promo = Version(1m, day, day.AddDays(1));

        Assert.True(promo.AppliesOn(day));
        Assert.False(promo.AppliesOn(day.AddDays(1)));
    }

    [Fact(DisplayName = "genuinely overlapping versions are rejected as ambiguous (price.overlap)")]
    public void Select_OverlappingVersions_RejectsAmbiguity()
    {
        var versions = new[]
        {
            Version(10m, new DateOnly(2026, 1, 1), null),
            Version(12m, new DateOnly(2026, 2, 1), null),
        };

        var error = Assert.Throws<BusinessRuleException>(() => PriceSelector.Select(versions, ProductId, new DateOnly(2026, 3, 1)));

        Assert.Equal("price.overlap", error.Code);
    }

    [Fact(DisplayName = "a version must end after it starts (price.range_invalid)")]
    public void Version_EndingOnItsStart_IsRejected()
    {
        var day = new DateOnly(2026, 3, 14);

        Assert.Equal("price.range_invalid", Assert.Throws<BusinessRuleException>(() => Version(1m, day, day)).Code);
    }
}

