using MeterForge.Kata;

// Ported from tests/MeterForge.Domain.Tests/Rating/TieredRaterTests.cs (incl. the docs/quality/FLAW-HARVEST.md
// Sprint 5 regression: 150 units across 100/$1 and remainder/$0.50 total exactly $125) plus unit conservation.
public sealed class TieredRaterTests
{
    private static readonly UsageTier[] TwoTiers =
    [
        new UsageTier(100, new Money(1m, "USD")),
        new UsageTier(null, new Money(0.50m, "USD")),
    ];

    [Fact(DisplayName = "50 units inside the first tier cost 50 and touch one tier")]
    public void Rate_QuantityWithinFirstTier_ChargesUnitsAtFirstPrice()
    {
        var result = TieredRater.Rate(50, TwoTiers);

        Assert.Equal(50m, result.Total.Amount);
        Assert.Single(result.Tiers);
    }

    [Fact(DisplayName = "150 units across 100/$1 + remainder/$0.50 total exactly $125 (FLAW-HARVEST Sprint 5)")]
    public void Rate_QuantityCrossingBoundary_ChargesEachUnitOnce()
    {
        var result = TieredRater.Rate(150, TwoTiers);

        Assert.Equal(125m, result.Total.Amount);
        Assert.Equal(50m, result.Tiers.Last().Units);
    }

    [Fact(DisplayName = "exactly 100 units fill the first tier and never reach the second")]
    public void Rate_QuantityAtBoundary_StaysInFirstTier()
    {
        var result = TieredRater.Rate(100, TwoTiers);

        Assert.Equal(100m, result.Total.Amount);
        Assert.Single(result.Tiers);
    }

    [Fact(DisplayName = "units are conserved: tier units sum to the rated quantity (250 over three tiers = $162.50)")]
    public void Rate_ThreeTiers_ConservesUnits()
    {
        var result = TieredRater.Rate(250, [
            new UsageTier(100, new Money(1m, "USD")),
            new UsageTier(200, new Money(0.50m, "USD")),
            new UsageTier(null, new Money(0.25m, "USD")),
        ]);

        Assert.Equal(250m, result.Tiers.Sum(t => t.Units));
        Assert.Equal(162.50m, result.Total.Amount);
    }

    [Fact(DisplayName = "mixed tier currencies are rejected (rating.currency_mismatch)")]
    public void Rate_MixedCurrencies_RejectsRule()
    {
        var error = Assert.Throws<BusinessRuleException>(() => TieredRater.Rate(10, [
            new UsageTier(100, new Money(1m, "USD")),
            new UsageTier(null, new Money(1m, "EUR")),
        ]));

        Assert.Equal("rating.currency_mismatch", error.Code);
    }
}

