namespace MeterForge.Kata;

public sealed class BusinessRuleException(string code, string message) : Exception(message)
{
    public string Code { get; } = code;
}

public readonly record struct Money
{
    public Money(decimal amount, string currency)
    {
        if (string.IsNullOrWhiteSpace(currency) || currency.Trim().Length != 3)
        {
            throw new BusinessRuleException("money.currency_invalid", "Currency must be a three-letter code.");
        }

        if (decimal.Round(amount, 2, MidpointRounding.ToEven) != amount)
        {
            throw new BusinessRuleException("money.precision_invalid", "Money supports at most two decimal places.");
        }

        Amount = amount;
        Currency = currency.Trim().ToUpperInvariant();
    }

    public decimal Amount { get; }

    public string Currency { get; }

    public static Money operator +(Money left, Money right)
    {
        if (left.Currency != right.Currency)
        {
            throw new BusinessRuleException("money.currency_mismatch", "Unlike currencies cannot be added.");
        }

        return new Money(left.Amount + right.Amount, left.Currency);
    }
}

public enum PaymentStatus { Pending, Succeeded, Failed }

public sealed class PaymentAttempt
{
    public PaymentAttempt(Guid id, string tenantId, Guid invoiceId, Money amount, string providerIdempotencyKey)
    {
        if (id == Guid.Empty || invoiceId == Guid.Empty) throw new BusinessRuleException("payment.identity_required", "Payment and invoice IDs are required.");
        if (amount.Amount <= 0) throw new BusinessRuleException("payment.amount_invalid", "Payment amount must be positive.");
        if (string.IsNullOrWhiteSpace(tenantId) || string.IsNullOrWhiteSpace(providerIdempotencyKey))
            throw new BusinessRuleException("payment.evidence_required", "Tenant and provider idempotency key are required.");
        Id = id;
        TenantId = tenantId;
        InvoiceId = invoiceId;
        Amount = amount;
        ProviderIdempotencyKey = providerIdempotencyKey;
    }

    public Guid Id { get; }
    public string TenantId { get; }
    public Guid InvoiceId { get; }
    public Money Amount { get; }
    public string ProviderIdempotencyKey { get; private set; }
    public PaymentStatus Status { get; private set; }
    public int AttemptNumber { get; private set; } = 1;
    public string? ProviderReference { get; private set; }

    public void Succeed(string providerReference)
    {
        if (Status != PaymentStatus.Pending || string.IsNullOrWhiteSpace(providerReference))
            throw new BusinessRuleException("payment.succeed_invalid", "Only a pending payment with provider evidence can succeed.");
        ProviderReference = providerReference;
        Status = PaymentStatus.Succeeded;
    }

    public void Fail() => Status = PaymentStatus.Failed;

    public void Retry()
    {
        if (Status != PaymentStatus.Failed) throw new BusinessRuleException("payment.retry_invalid", "Only a failed payment can retry.");
        AttemptNumber++;
        Status = PaymentStatus.Pending;
    }
}

public sealed record ProviderChargeRequest(string IdempotencyKey, Money Amount, Guid InvoiceId);
public sealed record ProviderChargeResult(bool Succeeded, string? ProviderReference);

public interface IPaymentProvider
{
    Task<ProviderChargeResult> ChargeAsync(ProviderChargeRequest request, CancellationToken cancellationToken);
}

public sealed class PaymentService(IPaymentProvider provider)
{
    public async Task<PaymentAttempt> CollectAsync(string tenantId, Guid invoiceId, Money amount, string idempotencyKey, CancellationToken cancellationToken)
    {
        var attempt = new PaymentAttempt(Guid.NewGuid(), tenantId, invoiceId, amount, idempotencyKey);
        await SendAsync(attempt, cancellationToken).ConfigureAwait(false);
        return attempt;
    }

    public async Task RetryAsync(PaymentAttempt attempt, CancellationToken cancellationToken)
    {
        attempt.Retry();
        await SendAsync(attempt, cancellationToken).ConfigureAwait(false);
    }

    private async Task SendAsync(PaymentAttempt attempt, CancellationToken cancellationToken)
    {
        var result = await provider.ChargeAsync(new ProviderChargeRequest(
            attempt.ProviderIdempotencyKey, attempt.Amount, attempt.InvoiceId), cancellationToken).ConfigureAwait(false);
        if (result.Succeeded) attempt.Succeed(result.ProviderReference!); else attempt.Fail();
    }
}

