using MeterForge.Kata;

// Ported from tests/MeterForge.Domain.Tests/Payments/PaymentAttemptTests.cs, plus the ambiguous-timeout drill of
// docs/operations/INCIDENT-DRILL.md:3 played against a provider that deduplicates by idempotency key.
public sealed class PaymentRetryTests
{
    /// <summary>Commits every NEW key exactly once; the first response is "lost", so the caller records a failure.</summary>
    private sealed class LossyProvider : IPaymentProvider
    {
        public readonly List<string> SeenKeys = [];
        public readonly HashSet<string> Charges = [];

        public Task<ProviderChargeResult> ChargeAsync(ProviderChargeRequest request, CancellationToken cancellationToken)
        {
            SeenKeys.Add(request.IdempotencyKey);
            Charges.Add(request.IdempotencyKey); // a repeated key is a replay, not a second charge
            return Task.FromResult(SeenKeys.Count == 1
                ? new ProviderChargeResult(false, null)
                : new ProviderChargeResult(true, "ch_" + request.IdempotencyKey));
        }
    }

    [Fact(DisplayName = "retry keeps the logical provider key and only advances the attempt number (FLAW-HARVEST Sprint 10)")]
    public void Retry_FailedAttempt_ReturnsToPendingAndIncrementsAttempt()
    {
        var payment = new PaymentAttempt(Guid.NewGuid(), "tenant-a", Guid.NewGuid(), new Money(10m, "USD"), "key-1");
        var logicalKey = payment.ProviderIdempotencyKey;
        payment.Fail();
        payment.Retry();

        Assert.Equal(PaymentStatus.Pending, payment.Status);
        Assert.Equal(2, payment.AttemptNumber);
        Assert.Equal(logicalKey, payment.ProviderIdempotencyKey);
    }

    [Fact(DisplayName = "a charge whose response was lost and is then retried is collected ONCE at the provider")]
    public async Task LostResponse_ThenRetry_ChargesOnce()
    {
        var provider = new LossyProvider();
        var service = new PaymentService(provider);

        var attempt = await service.CollectAsync("tenant-a", Guid.NewGuid(), new Money(25m, "USD"), "inv-42-pay", CancellationToken.None);
        Assert.Equal(PaymentStatus.Failed, attempt.Status);

        await service.RetryAsync(attempt, CancellationToken.None);

        Assert.Equal(PaymentStatus.Succeeded, attempt.Status);
        Assert.Equal(new[] { "inv-42-pay", "inv-42-pay" }, provider.SeenKeys);
        Assert.Single(provider.Charges);
    }

    [Fact(DisplayName = "only a failed payment can retry (payment.retry_invalid)")]
    public void Retry_PendingAttempt_IsRejected()
    {
        var payment = new PaymentAttempt(Guid.NewGuid(), "tenant-a", Guid.NewGuid(), new Money(10m, "USD"), "key-1");

        Assert.Equal("payment.retry_invalid", Assert.Throws<BusinessRuleException>(payment.Retry).Code);
    }

    [Fact(DisplayName = "success records the provider evidence")]
    public void Succeed_RecordsProviderEvidence()
    {
        var payment = new PaymentAttempt(Guid.NewGuid(), "tenant-a", Guid.NewGuid(), new Money(10m, "USD"), "key-1");
        payment.Succeed("provider-1");

        Assert.Equal("provider-1", payment.ProviderReference);
    }
}
